```

```zig
// 示例：居中显示、宽度跟随父容器
const text: vxfw.Text = .{
    .text = "Hello",
    .text_align = .center,
    .width_basis = .parent,
    .style = .{ .bold = true },
};
```

### RichText — 多样式文本

```zig
const RichText = struct {
    text: []const vaxis.Segment,   // Segment 数组，每段可有不同样式
    softwrap: bool = true,
};
```

### Border — 边框装饰

```zig
const Border = struct {
    child: vxfw.Widget,                 // 被包裹的 Widget
    style: vaxis.Style = .{},           // 边框样式
    labels: []const BorderLabel = &.{}, // 标签（可多个）
};

const BorderLabel = struct {
    text: []const u8,
    alignment: enum { top_left, top_center, top_right, bottom_left, bottom_center, bottom_right },
};
```

### Center — 居中容器

```zig
const Center = struct {
    child: vxfw.Widget,
};
```

### Padding — 内边距

```zig
const Padding = struct {
    child: vxfw.Widget,
    padding: struct { top: u16, bottom: u16, left: u16, right: u16 },
};
```

### SizedBox — 固定尺寸

```zig
const SizedBox = struct {
    child: ?vxfw.Widget = null,
    width: ?u16 = null,
    height: ?u16 = null,
};
```

### FlexColumn / FlexRow — 弹性布局

```zig
const FlexColumn = struct {  // 垂直排列
    children: []vxfw.FlexItem,
};

const FlexRow = struct {     // 水平排列
    children: []vxfw.FlexItem,
};

const FlexItem = struct {
    widget: Widget,
    flex: u8 = 1,   // 0 = 固有尺寸，>0 = 按比例分配剩余空间
