```

### ScrollView — 滚动容器

```zig
const ScrollView = struct {
    children: Source,                    // .slice 或 .builder
    cursor: u32 = 0,                    // 当前选中项索引
    draw_cursor: bool = false,          // 是否绘制选择指示器
    wheel_scroll: u8 = 3,              // 鼠标滚轮步长

    pub const Source = union(enum) {
        slice: []const vxfw.Widget,      // 静态列表
