```

内置 j/k/Ctrl+D/Ctrl+U/鼠标滚轮 支持。

### ScrollBars — 滚动条

```zig
const ScrollBars = struct {
    scroll_view: ScrollView,             // 注意：是值，不是指针
};
```

### 其他

- **Button** — 按钮（可聚焦，Enter/Space 触发）
- **Spinner** — 加载动画
- **TextField** — 文本输入框
- **ListView** — 列表视图

---

## 11. 常用模式

### 模式 A：事件委托

将事件传递给内置 Widget 处理（`05_scroll_view.zig`）:

```zig
fn typeErasedEventHandler(ptr: *anyopaque, ctx: *vxfw.EventContext, event: vxfw.Event) anyerror!void {
    const self: *Reader = @ptrCast(@alignCast(ptr));
    switch (event) {
        .key_press => |key| {
            if (key.matches('q', .{})) { ctx.quit = true; return; }
        },
        else => {},
    }
    // 将未处理的事件委托给 ScrollView
    try self.scroll_bars.scroll_view.handleEvent(ctx, event);
}
```

### 模式 B：SurfaceWidget（Surface → Widget 适配器）

Border 等容器需要 Widget，但你已经有了 Surface。用一个小包装器转换（`02_counter.zig`）:

```zig
const SurfaceWidget = struct {
    surface: vxfw.Surface,
    self_widget: vxfw.Widget,

    pub fn widget(self: *const SurfaceWidget) vxfw.Widget {
        return .{
            .userdata = @constCast(self),
            .drawFn = typeErasedDrawFn,
        };
    }

    fn typeErasedDrawFn(ptr: *anyopaque, _: vxfw.DrawContext) std.mem.Allocator.Error!vxfw.Surface {
        const self: *const SurfaceWidget = @ptrCast(@alignCast(ptr));
        return self.surface;
    }
};

// 使用：在 arena 上分配，传给 Border
const wrapper = try ctx.arena.create(SurfaceWidget);
wrapper.* = .{ .surface = inner_surface, .self_widget = self.widget() };
const border: vxfw.Border = .{ .child = wrapper.widget() };
```

### 模式 C：子约束修改

给子区域一个不同的约束（`03_layout.zig`）:

```zig
// 标题栏占 1 行，剩余给内容区
const content_ctx = ctx.withConstraints(
    .{ .width = 0, .height = 0 },
    .{
        .width = ctx.max.width,
        .height = if (ctx.max.height) |h| h -| 1 else null,
    },
);
```

### 模式 D：arena 字符串格式化

在 `drawFn` 中构造动态文本（`02_counter.zig`）:

```zig
const count_str = try std.fmt.allocPrint(ctx.arena, "Count: {d}", .{self.count});
const text: vxfw.Text = .{ .text = count_str };
```

不需要 free——arena 在帧结束时统一释放。

### 模式 E：手动计算子 Widget 位置

逐个绘制子 Widget，累积行号（`04_rich_text.zig`）:

```zig
const children = try ctx.arena.alloc(vxfw.SubSurface, 4);

const s1 = try section1.widget().draw(ctx);
children[0] = .{ .origin = .{ .row = 0, .col = 0 }, .surface = s1 };

var row: i17 = s1.size.height;
const s2 = try section2.widget().draw(ctx);
children[1] = .{ .origin = .{ .row = row, .col = 0 }, .surface = s2 };

row += s2.size.height;
// ...
```

